import React, { useState, useEffect, useCallback, useMemo } from 'react';
import api from '../config/axiosConfig';
import { useAuth } from '../context/AuthContext';
import { useNotification } from '../context/NotificationContext';
import { User, Department, Company, ApiResponseError } from '../types';
import { isAxiosErrorTypeGuard } from '../utils/typeGuards';
import { toast } from 'react-toastify';
import UserFormModal from '../components/Users/UserFormModal';
import ResetPasswordModal from '../components/Users/ResetPasswordModal';
import UserPermissionsModal from '../components/Users/UserPermissionsModal';
import { PERMISSION_KEYS as P } from '../constants/permissions';
import { canManagePermissions, hasPermission, isSuperAdmin } from '../utils/permissions';
import { clInput } from '../utils/cleanLightUi';
import { UserRole } from '../types';

const ROLE_LABELS: Record<UserRole, string> = {
    admin: 'Administrador',
    agent: 'Agente',
    client: 'Cliente',
    boss: 'Jefe',
    purchasing: 'Compras',
    supplier: 'Proveedor',
};

const AdminUsersPage: React.FC = () => {
    const { user } = useAuth();
    const { addNotification } = useNotification();

    const [users, setUsers] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    
    const [isUserModalOpen, setIsUserModalOpen] = useState(false);
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [isResetModalOpen, setIsResetModalOpen] = useState(false);
    const [selectedUserForReset, setSelectedUserForReset] = useState<User | null>(null);
    const [permissionsTarget, setPermissionsTarget] = useState<User | null>(null);
    const [isPermissionsModalOpen, setIsPermissionsModalOpen] = useState(false);

    const [allDepartments, setAllDepartments] = useState<Department[]>([]);
    const [allCompanies, setAllCompanies] = useState<Company[]>([]);

    const [filters, setFilters] = useState({
        search: '',
        role: '',
        companyId: '',
        departmentId: '',
    });

    const fetchMeta = useCallback(async () => {
        try {
            const [deptsRes, companiesRes] = await Promise.all([
                api.get('/api/departments'),
                api.get('/api/companies'),
            ]);
            setAllDepartments(deptsRes.data.data || []);
            setAllCompanies(companiesRes.data.data || []);
        } catch (err: unknown) {
            const message = isAxiosErrorTypeGuard(err)
                ? (err.response?.data as ApiResponseError)?.message || 'Error al cargar empresas/departamentos.'
                : 'Ocurrió un error inesperado.';
            addNotification(message, 'error');
        }
    }, [addNotification]);

    const fetchUsers = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            const params = new URLSearchParams();
            if (filters.search.trim()) params.append('search', filters.search.trim());
            if (filters.role) params.append('role', filters.role);
            if (filters.companyId) params.append('companyId', filters.companyId);
            if (filters.departmentId) params.append('departmentId', filters.departmentId);

            const qs = params.toString();
            const usersRes = await api.get(`/api/users${qs ? `?${qs}` : ''}`);
            setUsers(usersRes.data.data || []);
        } catch (err: unknown) {
            const message = isAxiosErrorTypeGuard(err)
                ? (err.response?.data as ApiResponseError)?.message || 'Error al cargar los usuarios.'
                : 'Ocurrió un error inesperado.';
            setError(message);
            addNotification(message, 'error');
        } finally {
            setLoading(false);
        }
    }, [filters, addNotification]);

    useEffect(() => {
        if (user?.role === 'admin' && hasPermission(user, P.USERS_VIEW)) {
            fetchMeta();
        }
    }, [user, fetchMeta]);

    useEffect(() => {
        if (user?.role === 'admin' && hasPermission(user, P.USERS_VIEW)) {
            const t = setTimeout(() => fetchUsers(), filters.search ? 350 : 0);
            return () => clearTimeout(t);
        }
    }, [user, fetchUsers, filters.search]);

    const departmentsForFilter = useMemo(() => {
        if (!filters.companyId) return allDepartments;
        const cid = parseInt(filters.companyId, 10);
        return allDepartments.filter((d) => d.company_id === cid);
    }, [allDepartments, filters.companyId]);

    const hasActiveFilters =
        !!filters.search || !!filters.role || !!filters.companyId || !!filters.departmentId;

    const refreshAll = useCallback(async () => {
        await fetchUsers();
    }, [fetchUsers]);

    const handleCreateUser = () => {
        setCurrentUser(null);
        setIsUserModalOpen(true);
    };

    const handleEditUser = (userToEdit: User) => {
        setCurrentUser(userToEdit);
        setIsUserModalOpen(true);
    };

    const handleSaveUser = async (userData: Partial<User>) => {
        const url = currentUser ? `/api/users/${currentUser.id}` : '/api/users';
        const method = currentUser ? 'put' : 'post';
        const action = currentUser ? 'actualizado' : 'creado';

        try {
            await api[method](url, userData);
            addNotification(`Usuario ${action} exitosamente.`, 'success');
            setIsUserModalOpen(false);
            refreshAll();
        } catch (err: unknown) {
            const message = isAxiosErrorTypeGuard(err) ? (err.response?.data as ApiResponseError)?.message || `Error al guardar usuario.` : 'Error inesperado.';
            addNotification(message, 'error');
        }
    };

    const handleDeleteUser = async (userId: number) => {
        if (!window.confirm('¿Estás seguro? Esta acción es irreversible.')) return;
        try {
            await api.delete(`/api/users/${userId}`);
            addNotification('Usuario eliminado exitosamente.', 'success');
            refreshAll();
        } catch (err: unknown) {
            const message = isAxiosErrorTypeGuard(err) ? (err.response?.data as ApiResponseError)?.message || 'Error al eliminar usuario.' : 'Error inesperado.';
            addNotification(message, 'error');
        }
    };

    const handleOpenResetModal = (userToReset: User) => {
        setSelectedUserForReset(userToReset);
        setIsResetModalOpen(true);
    };

    const handleConfirmResetPassword = async (newPassword: string) => {
        if (!selectedUserForReset) return;
        try {
            await api.put(`/api/users/${selectedUserForReset.id}/reset-password`, { newPassword });
            toast.success(`Contraseña para ${selectedUserForReset.username} actualizada.`);
        } catch (err: any) {
            const message = err.response?.data?.message || "Error al resetear la contraseña.";
            toast.error(message);
        }
    };

    if (loading) return <div className="text-center p-8">Cargando usuarios...</div>;
    if (error) return <div className="text-center p-8 text-red-500">Error: {error}</div>;

    return (
        <>
            <div className="container mx-auto p-4 sm:p-6 lg:p-8 bg-gray-50 min-h-screen">
                <div className="flex flex-col sm:flex-row justify-between sm:items-center gap-4 mb-6">
                    <h1 className="text-2xl sm:text-3xl font-bold text-gray-800">Gestión de Usuarios</h1>
                    {hasPermission(user, P.USERS_CREATE) && (
                        <button onClick={handleCreateUser} className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded-lg shadow-md self-start sm:self-center">
                            Crear Nuevo Usuario
                        </button>
                    )}
                </div>

                <div className="bg-white p-4 rounded-lg shadow-md mb-6 border border-gray-100">
                    <h2 className="text-sm font-bold text-gray-800 mb-3">Buscar y filtrar</h2>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-3">
                        <div className="lg:col-span-2">
                            <label className="block text-xs font-semibold text-gray-600 mb-1">
                                Búsqueda (usuario, email, nombre)
                            </label>
                            <input
                                type="text"
                                value={filters.search}
                                onChange={(e) => setFilters((f) => ({ ...f, search: e.target.value }))}
                                className={clInput}
                                placeholder="Ej: jperez, bacarsa.com..."
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-semibold text-gray-600 mb-1">Rol</label>
                            <select
                                value={filters.role}
                                onChange={(e) => setFilters((f) => ({ ...f, role: e.target.value }))}
                                className={clInput}
                            >
                                <option value="">Todos</option>
                                {(Object.keys(ROLE_LABELS) as UserRole[]).map((r) => (
                                    <option key={r} value={r}>
                                        {ROLE_LABELS[r]}
                                    </option>
                                ))}
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-semibold text-gray-600 mb-1">Empresa</label>
                            <select
                                value={filters.companyId}
                                onChange={(e) =>
                                    setFilters((f) => ({
                                        ...f,
                                        companyId: e.target.value,
                                        departmentId: '',
                                    }))
                                }
                                className={clInput}
                            >
                                <option value="">Todas</option>
                                {allCompanies.map((company) => (
                                    <option key={company.id} value={company.id}>
                                        {company.name}
                                    </option>
                                ))}
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-semibold text-gray-600 mb-1">Departamento</label>
                            <select
                                value={filters.departmentId}
                                onChange={(e) =>
                                    setFilters((f) => ({ ...f, departmentId: e.target.value }))
                                }
                                className={clInput}
                            >
                                <option value="">Todos</option>
                                {departmentsForFilter.map((dept) => (
                                    <option key={dept.id} value={dept.id}>
                                        {dept.name}
                                    </option>
                                ))}
                            </select>
                        </div>
                    </div>
                    <div className="mt-3 flex flex-wrap items-center gap-3">
                        {hasActiveFilters && (
                            <button
                                type="button"
                                onClick={() =>
                                    setFilters({ search: '', role: '', companyId: '', departmentId: '' })
                                }
                                className="text-sm text-red-600 hover:text-red-800 font-semibold"
                            >
                                Limpiar filtros
                            </button>
                        )}
                        <span className="text-sm text-gray-500 ml-auto">
                            {users.length} {users.length === 1 ? 'usuario mostrado' : 'usuarios mostrados'}
                        </span>
                    </div>
                </div>

                {user?.role === 'admin' && !canManagePermissions(user) && (
                    <div className="mb-4 rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900">
                        Para ver el botón <strong>Permisos</strong> necesitás ser super administrador o tener el
                        permiso de gestión de permisos. Cerrá sesión y volvé a entrar.
                    </div>
                )}
                {canManagePermissions(user) && (
                    <p className="mb-4 text-sm text-slate-600">
                        En filas con rol <strong>admin</strong> o <strong>agent</strong>, usá <strong>Permisos</strong> para definir qué puede ver cada uno.
                        {isSuperAdmin(user) && (
                            <span className="ml-1 text-emerald-700">(Tu usuario es super administrador.)</span>
                        )}
                    </p>
                )}

                <div className="bg-white p-4 sm:p-6 rounded-lg shadow-lg">
                    {users.length === 0 ? (
                        <p className="text-gray-600 text-center py-8">No hay usuarios que coincidan con el filtro.</p>
                    ) : (
                        <>
                            {/* ✅ VISTA DE TABLA PARA ESCRITORIO (md y superior) */}
                            <table className="min-w-full divide-y divide-gray-200 hidden md:table">
                               <thead className="bg-gray-50">
                                    <tr>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Username</th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Email</th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Rol</th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Empresa</th>
                                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">Acciones</th>
                                    </tr>
                                </thead>
                                <tbody className="bg-white divide-y divide-gray-200">
                                    {users.map((userItem) => (
                                        <tr key={userItem.id}>
                                            <td className="px-6 py-4 whitespace-nowrap">{userItem.username}</td>
                                            <td className="px-6 py-4 whitespace-nowrap">{userItem.email}</td>
                                            <td className="px-6 py-4 whitespace-nowrap">{userItem.role}</td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{allCompanies.find(c => c.id === userItem.company_id)?.name || 'N/A'}</td>
                                            <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                                {hasPermission(user, P.USERS_EDIT) && (
                                                    <button onClick={() => handleEditUser(userItem)} className="text-indigo-600 hover:text-indigo-900 mr-4">Editar</button>
                                                )}
                                                {hasPermission(user, P.USERS_RESET_PASSWORD) && (
                                                    <button onClick={() => handleOpenResetModal(userItem)} className="text-yellow-600 hover:text-yellow-900 mr-4">Resetear</button>
                                                )}
                                                {(userItem.role === 'admin' || userItem.role === 'agent') &&
                                                    canManagePermissions(user) && (
                                                    <button
                                                        onClick={() => {
                                                            setPermissionsTarget(userItem);
                                                            setIsPermissionsModalOpen(true);
                                                        }}
                                                        className="text-blue-700 hover:text-blue-900 mr-4"
                                                    >
                                                        Permisos
                                                    </button>
                                                )}
                                                {hasPermission(user, P.USERS_DELETE) && (
                                                    <button onClick={() => handleDeleteUser(userItem.id)} className="text-red-600 hover:text-red-900">Eliminar</button>
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>

                            {/* ✅ VISTA DE TARJETAS PARA MÓVILES (hasta md) */}
                            <div className="md:hidden space-y-4">
                                {users.map((userItem) => (
                                    <div key={userItem.id} className="bg-gray-50 p-4 rounded-lg border">
                                        <div className="flex justify-between items-start">
                                            <div>
                                                <p className="font-bold text-gray-800">{userItem.username}</p>
                                                <p className="text-sm text-gray-600">{userItem.email}</p>
                                            </div>
                                            <span className="text-xs bg-blue-100 text-blue-800 px-2 py-1 rounded-full flex-shrink-0 ml-2">{userItem.role}</span>
                                        </div>
                                        <div className="text-sm text-gray-600 mt-2">
                                            <p><strong>Empresa:</strong> {allCompanies.find(c => c.id === userItem.company_id)?.name || 'N/A'}</p>
                                        </div>
                                        <div className="mt-4 pt-2 border-t flex justify-end gap-4 text-sm flex-wrap">
                                            {hasPermission(user, P.USERS_EDIT) && (
                                                <button onClick={() => handleEditUser(userItem)} className="text-indigo-600 font-semibold hover:underline">Editar</button>
                                            )}
                                            {hasPermission(user, P.USERS_RESET_PASSWORD) && (
                                                <button onClick={() => handleOpenResetModal(userItem)} className="text-yellow-600 font-semibold hover:underline">Resetear</button>
                                            )}
                                            {(userItem.role === 'admin' || userItem.role === 'agent') &&
                                                canManagePermissions(user) && (
                                                <button
                                                    onClick={() => {
                                                        setPermissionsTarget(userItem);
                                                        setIsPermissionsModalOpen(true);
                                                    }}
                                                    className="text-blue-700 font-semibold hover:underline"
                                                >
                                                    Permisos
                                                </button>
                                            )}
                                            {hasPermission(user, P.USERS_DELETE) && (
                                                <button onClick={() => handleDeleteUser(userItem.id)} className="text-red-600 font-semibold hover:underline">Eliminar</button>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </>
                    )}
                </div>
            </div>

            {isUserModalOpen && (
                <UserFormModal
                    isOpen={isUserModalOpen}
                    onClose={() => setIsUserModalOpen(false)}
                    onSave={handleSaveUser}
                    onCreated={refreshAll}
                    initialData={currentUser}
                    departments={allDepartments}
                    companies={allCompanies}
                />
            )}
            
            <ResetPasswordModal
                isOpen={isResetModalOpen}
                onClose={() => setIsResetModalOpen(false)}
                onConfirm={handleConfirmResetPassword}
                user={selectedUserForReset}
            />

            <UserPermissionsModal
                isOpen={isPermissionsModalOpen}
                onClose={() => {
                    setIsPermissionsModalOpen(false);
                    setPermissionsTarget(null);
                }}
                targetUser={permissionsTarget}
                onSaved={refreshAll}
                canGrantSuperAdmin={!!user?.is_super_admin}
            />
        </>
    );
};

export default AdminUsersPage;